package com.projexa.coaching.users.entity;
import jakarta.persistence.*; import java.time.LocalDateTime; import java.util.UUID;
@Entity @Table(name="refresh_tokens") public class RefreshToken { @Id @GeneratedValue(strategy=GenerationType.UUID) private UUID id; @Column(nullable=false) private UUID userId; @Column(nullable=false) private String tokenHash; @Column(nullable=false) private LocalDateTime expiresAt; private LocalDateTime revokedAt; private LocalDateTime createdAt=LocalDateTime.now(); private LocalDateTime lastUsedAt; public UUID getId(){return id;} public UUID getUserId(){return userId;} public String getTokenHash(){return tokenHash;} public LocalDateTime getExpiresAt(){return expiresAt;} public LocalDateTime getRevokedAt(){return revokedAt;} public void setUserId(UUID v){userId=v;} public void setTokenHash(String v){tokenHash=v;} public void setExpiresAt(LocalDateTime v){expiresAt=v;} public void setRevokedAt(LocalDateTime v){revokedAt=v;} public void setLastUsedAt(LocalDateTime v){lastUsedAt=v;} }
